INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28173$nota-0177$m28173$, $m28174$Manual treinamento.pdf$m28174$, $m28175$86$m28175$, $m28176$A Potência Crítica (Critical Power)... representa a maior potência teoricamente sustentável sem perda contínua da homeostase metabólica. Diversos estudos sugerem que a Potência Crítica apresenta forte relação com o domínio severo do exercício. Embora frequentemente próxima ao MLSS, trata-se de um conceito matemático derivado da relação potência-tempo.$m28176$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28177$nota-0177$m28177$, $m28178$nota-0026$m28178$, $m28179$complementa$m28179$, $m28180$reforça e recontextualiza fisiologicamente o modelo de Potência Crítica já registrado na nota-0026 do Livro 1, situando-o em relação ao MLSS/LT2 (nota-0172, nota-0174)$m28180$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28181$nota-0177$m28181$, $m28182$nota-0172$m28182$, $m28183$complementa$m28183$, $m28184$LT2, citado no corpo da nota como referência de comparação da Potência Crítica — link estrutural ausente até auditoria de 2026-08-02$m28184$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28185$nota-0177$m28185$, $m28186$nota-0174$m28186$, $m28187$complementa$m28187$, $m28188$MLSS, citado no corpo da nota como o conceito fisiológico mais próximo (mas não idêntico) da Potência Crítica — link estrutural ausente até auditoria de 2026-08-02$m28188$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28189$nota-0185$m28189$, $m28190$Manual treinamento.pdf$m28190$, $m28191$111$m28191$, $m28192$Potência informa a carga externa. Frequência cardíaca informa parte da carga interna. Percepção subjetiva informa a resposta global do organismo. Cada variável fornece informações diferentes. O treinador moderno integra todas elas.$m28192$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28193$nota-0185$m28193$, $m28194$Manual treinamento.pdf$m28194$, $m28195$108$m28195$, $m28196$potência também possui limitações. Ela informa quanto trabalho está sendo produzido. Não informa quanto esforço fisiológico foi necessário para produzi-lo. Por isso, potência e frequência cardíaca devem ser interpretadas de forma complementar.$m28196$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28197$nota-0185$m28197$, $m28198$nota-0158$m28198$, $m28199$complementa$m28199$, $m28200$reforça, com uma distinção conceitual mais ampla (carga externa vs. interna), a cautela já registrada na nota-0158 sobre interpretar FC em contexto$m28200$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28201$nota-0191$m28201$, $m28202$Manual treinamento.pdf$m28202$, $m28203$141$m28203$, $m28204$Carga externa: representa o trabalho realizado (potência, velocidade, distância, tempo, desnível, repetições). Carga interna: representa a resposta do organismo ao trabalho realizado (FC, lactato, RPE, VFC, respostas hormonais)... Treinadores prescrevem carga externa. O organismo adapta-se à carga interna.$m28204$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28205$nota-0191$m28205$, $m28206$Manual treinamento.pdf$m28206$, $m28207$143$m28207$, $m28208$A adaptação ao treinamento segue uma lógica semelhante à de um medicamento... Quando a carga é insuficiente, a adaptação tende a ser pequena. Quando é excessiva, aumenta o risco de fadiga crônica. Entre esses extremos existe uma faixa ótima de estímulo. Essa relação é conhecida como curva dose-resposta.$m28208$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28209$nota-0191$m28209$, $m28210$nota-0185$m28210$, $m28211$complementa$m28211$, $m28212$formaliza, sob os termos 'carga externa/interna', a mesma distinção já registrada na nota-0185 (potência = carga externa, FC = carga interna)$m28212$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28213$nota-0194$m28213$, $m28214$Manual treinamento.pdf$m28214$, $m28215$145$m28215$, $m28216$O TSS mede carga mecânica. Não mede fadiga. Nem recuperação. Muito menos adaptação. Ele representa apenas uma estimativa da carga externa ponderada pela intensidade.$m28216$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28217$nota-0194$m28217$, $m28218$nota-0062$m28218$, $m28219$complementa$m28219$, $m28220$acrescenta uma ressalva importante de interpretação à definição operacional de TSS já registrada na nota-0062 do Livro 1$m28220$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28221$nota-0212$m28221$, $m28222$VO2 Max Essentials_Final.pdf$m28222$, $m28223$27$m28223$, $m28224$Performance VO2 refers to the rate of oxygen consumption during an endurance performance bout and is used as a practical estimation of actual metabolic energy production and ATP turnover. In other words, rather than your maximal VO2, performance VO2 is your rate of oxygen consumption during a competition, whilst you're running at various speeds or producing a certain power output.$m28224$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28225$nota-0212$m28225$, $m28226$nota-0164$m28226$, $m28227$complementa$m28227$, $m28228$formaliza, com um nome próprio ('Performance VO2'), a distinção já reforçada na nota-0164 entre potencial aeróbio máximo (VO2máx) e a fração dele realmente utilizada durante a competição$m28228$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28229$nota-0002$m28229$, $m28230$Training and Racing with a Power Meter.pdf$m28230$, $m28231$32$m28231$, $m28232$By definition, there are 4.184 kJ per Calorie, so at first glance it would seem that to determine your energy expenditure using power-meter data, you would simply divide your total work in kJ by 4.184.$m28232$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m28233$nota-0002$m28233$, $m28234$Training and Racing with a Power Meter.pdf$m28234$, $m28235$33$m28235$, $m28236$you would need to first divide your total work in kilojoules by 4.184, but then multiply this result by either 4 (if efficiency is at 25 percent) or 5 (if efficiency is at 20 percent)... you can also take the value for the total work performed in kJ as an estimate of your energy expenditure in kilocalories.$m28236$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m28237$nota-0002$m28237$, $m28238$nota-0123$m28238$, $m28239$complementa$m28239$, $m28240$nota-0123 aplica esta mesma conversão kJ→kcal a um exemplo real de prova do livro (p. 358), usando uma razão de 1:1,1 (2.000 kJ ≈ 2.200 kcal) em vez do 1:1 tratado aqui como simplificação — ver ressalva de precisão abaixo$m28240$)
